cat > source/common.py <<'PY'
"""Shared sample representation and command-line diagnostics."""
import sys, math, os, re, json, pkgutil, copy
MAX = 2147483647
MIN = -2147483648
UNIT = 2147483648.0

class Failure(Exception):
    def __init__(self, code=1): self.code=code

class Context:
    def __init__(self):
        self.prog=sys.argv[0]
        self.verbosity=2
        self.no_dither=False
        self.repeatable=False
        self.progress=False
        self.combine='concatenate'
        self.guard=False
        self.normalize=False
        self.plot=None
        self.buffer=8192
        self.clobber=True
        self.rng=0
        self.help=json.loads(pkgutil.get_data(__name__, 'help_data.json').decode())
        self.clips=[]
        self.chain=[]
        self.effects=[]
        self.outbits=32
        self.out_rate=None
        self.out_channels=None
        self.outname=''
        self.headroom=1.0
    def log(self, level, module, text):
        if self.verbosity >= {'FAIL':1,'WARN':2,'INFO':3,'DBUG':4}[level]:
            sys.stderr.write('%s %s %s: %s\n'%(self.prog,level,module,text))
    def fail(self, module, text, code=1):
        self.log('FAIL',module,text); raise Failure(code)
    def usage(self, name):
        text=self.help['effects'].get(name,'')
        marker='\n'+name+' '
        if marker in text:
            text=text.split(marker,1)[1].rstrip('\n')
            text=text.split('\n\n`',1)[0]
        else: text=''
        self.fail(name, 'usage: '+text)
    def warn(self,module,text): self.log('WARN',module,text)
    def version(self): return self.prog+':      SoX v14.4.2\n'
    def random(self):
        self.rng=(1664525*self.rng+1013904223)&0xffffffff
        return self.rng if self.rng<0x80000000 else self.rng-0x100000000
    def clipwarn(self, module, n):
        if n:self.clips.append((module,int(n)))

class Audio:
    def __init__(self, data=None, rate=48000, channels=1, bits=32, encoding='signed-integer', **kw):
        self.data=data if data is not None else []
        self.rate=float(rate);self.channels=int(channels);self.bits=bits;self.encoding=encoding
        self.precision=kw.get('precision',precision(encoding,bits))
        self.comments=kw.get('comments',[])
        self.name=kw.get('name',''); self.ftype=kw.get('ftype','null')
        self.endian=kw.get('endian','little')
        self.file_size=kw.get('file_size',0)
        self.known=kw.get('known',True)
        self.infinite=kw.get('infinite',False)
        self.frames_header=kw.get('frames_header',None)
        self.reverse_bits=False;self.reverse_nibbles=False
    @property
    def frames(self):return len(self.data)//self.channels
    @property
    def length(self):
        if not self.known:return 0
        return self.frames_header if self.frames_header is not None else self.frames
    def modified(self, data, channels=None, rate=None, precision=None):
        a=copy.copy(self);a.data=data
        a.frames_header=None
        if channels is not None:a.channels=channels
        if rate is not None:a.rate=rate
        if precision is not None:a.precision=precision
        return a

def precision(enc,bits):
    return {'floating-point':25 if bits==32 else 54,'text':54,'mu-law':14,'a-law':13,'ima-adpcm':13,'ms-adpcm':14,'oki-adpcm':12}.get(enc,bits)

def rounding(v):
    if v>=0:return int(v+0.5)
    return int(v-0.5)

def sample(v, mode='round'):
    if not math.isfinite(v):return 0,0
    if v>MAX:return MAX,1
    if v<MIN:return MIN,1
    return (int(v) if mode=='trunc' else rounding(v)),0

def scaled(data, factor, ctx, name, mode='round'):
    out=[];clips=0
    for x in data:
        y,c=sample(x*factor,mode);out.append(y);clips+=c
    ctx.clipwarn(name,clips)
    return out

def db(x):return 20*math.log10(abs(x)) if x else -math.inf

def fmt_num(v):return '%g'%v

def compact(v):
    suffix=''
    for s in ['', 'k', 'M', 'G', 'T', 'P']:
        suffix=s
        if abs(v)<1000:break
        v/=1000.
    if not suffix:return '%g'%v
    return ('%.3g'%v)+suffix

def compact3(v):
    # Statistics preserve trailing zeroes on scaled counts.
    if abs(v)<1000:return '%g'%v
    s=''
    for s in ['k','M','G','T','P']:
        v/=1000
        if abs(v)<1000:break
    digits=max(0,2-int(math.floor(math.log10(abs(v))))) if v else 2
    return ('%.*f'%(digits,v))+s

def duration(seconds):
    if seconds<0 or not math.isfinite(seconds):seconds=0
    centis=int(seconds*100+0.5)
    return '%02d:%02d:%05.2f'%(centis//360000,(centis//6000)%60,(centis%6000)/100.)

def parse_number(s, kilo=False):
    if kilo and s.lower().endswith('k'):return float(s[:-1])*1000
    return float(s)

def time_samples(s,rate):
    """Parse chained SoX-style sample and wall-clock time expressions."""
    s=str(s)
    if not s:raise ValueError()
    parts=re.split(r'(?<![eE])([+-])',s)
    ans=0.;sign=1
    for p in parts:
        if not p:continue
        if p in ('+','-'):sign=1 if p=='+' else -1;continue
        if p.endswith('s'):
            v=float(p[:-1])
        else:
            if p.endswith('t'):p=p[:-1]
            v=0
            for n in p.split(':'):v=v*60+(float(n) if n else 0.)
            v*=rate
        if not math.isfinite(v) or v<0:raise ValueError()
        ans+=sign*v
    return rounding(ans)

def position(s,rate,length,previous=0,relative=False):
    if s.startswith('='):return max(0,time_samples(s[1:],rate))
    if s.startswith('-'):return max(0,length-time_samples(s[1:],rate))
    if s.startswith('+'):return max(0,previous+time_samples(s[1:],rate))
    return max(0,(previous if relative else 0)+time_samples(s,rate))

ENC_NAMES={'signed-integer':'Signed Integer PCM','unsigned-integer':'Unsigned Integer PCM',
           'floating-point':'Floating Point PCM','text':'Floating Point (text) PCM',
           'mu-law':'u-law','a-law':'A-law','ima-adpcm':'IMA ADPCM','ms-adpcm':'MS ADPCM',
           'oki-adpcm':'OKI ADPCM','cvsd':'CVSD','gsm-full-rate':'GSM','lpc10':'LPC10'}

def encoding_name(a,with_bits=False):
    s=ENC_NAMES.get(a.encoding,a.encoding)
    if with_bits and a.bits:s=str(a.bits)+'-bit '+s
    return s

def metadata(a,output=False,verbose=False):
    label='Output File    ' if output else 'Input File     '
    name=a.name
    s="\n%s: '%s'\n"%(label,name)
    s+='Channels       : %d\n'%a.channels
    s+='Sample Rate    : %g\n'%a.rate
    s+='Precision      : %d-bit\n'%a.precision
    n=a.length
    if not output and n:
        s+='Duration       : %s = %d samples ~ %g CDDA sectors\n'%(duration(n/a.rate),n,n/a.rate*75)
        if a.file_size:
            s+='File Size      : %s\n'%compact(a.file_size)
            s+='Bit Rate       : %s\n'%compact(a.file_size*8*a.rate/n)
    s+='Sample Encoding: %s\n'%encoding_name(a,True)
    if verbose:
        if a.bits>8 and a.ftype not in ('null','dat'):
            s+='Endian Type    : %s\n'%a.endian
        s+='Reverse Nibbles: %s\n'%('yes' if a.reverse_nibbles else 'no')
        s+='Reverse Bits   : %s\n'%('yes' if a.reverse_bits else 'no')
    if a.comments:
        if len(a.comments)==1 and '\n' not in a.comments[0]:s+="Comment        : '%s'\n"%a.comments[0]
        else:s+='Comments       : \n'+'\n'.join(a.comments)+'\n'
    return s+'\n'
PY"}

