        sys.stdout.write(ctx.version()+ctx.help['info']);return 0
    rc=0;dur=0.;nums=0;count=0
    for filename in files:
        try:a=read_audio({'name':filename},ctx,True)
        except Failure:rc=1;continue
        count+=1;nums+=a.length;dur+=a.length/a.rate
        if total and opt in ('s','d','D'):continue
        value=None
        if opt=='t':value=a.ftype
        elif opt=='r':value=fmt_num(a.rate)
        elif opt=='c':value=str(a.channels)
        elif opt=='s':value=str(a.length)
        elif opt=='d':value=duration(a.length/a.rate)
        elif opt=='D':value='%.6f'%(a.length/a.rate)
        elif opt=='b':value=str(a.bits)
        elif opt=='B':value=compact(a.file_size*8*a.rate/a.length) if a.length else '0'
        elif opt=='p':value=str(a.precision)
        elif opt=='e':value=encoding_name(a)
        elif opt=='a':
            if a.comments:sys.stdout.write('\n'.join(a.comments)+'\n')
        else:sys.stdout.write(metadata(a))
        if value is not None:sys.stdout.write(value+'\n')
    if total and opt in ('s','d','D'):
        sys.stdout.write((str(nums) if opt=='s' else duration(dur) if opt=='d' else '%.6f'%dur)+'\n')
    elif opt is None and count>1:sys.stdout.write('Total Duration of %d files: %s\n'%(count,duration(dur)))
