                    if val not in choices:help_main(ctx,1,"combine type `%s' is not valid"%val)
                    ctx.combine=val
                elif key=='plot':
                    if val not in ('gnuplot','octave','off'):help_main(ctx,1,'invalid plot type')
                    ctx.plot=None if val=='off' else val
                elif key in ('buffer','input-buffer','dft-min'):
                    try:v=int(val)
                    except ValueError:help_main(ctx,1,'invalid buffer size')
                    if v<1:help_main(ctx,1,'Buffer size `%s' is not valid'%val)
                    if key=='buffer':ctx.buffer=v
                elif key in ('multi-threaded','single-threaded','play-rate-arg','replay-gain','temp'):pass
                elif key=='effects-file':effects_file=val
                elif key in ('type','encoding','endian'):
                    if key=='type':current[key]=val.lower().lstrip('.')
                    elif key=='encoding':
                        matches=[v for v in ('signed-integer','unsigned-integer','floating-point','mu-law','a-law','ima-adpcm','ms-adpcm','gsm-full-rate','oki-adpcm') if v.startswith(val.lower())]
                        if val.lower()=='float':matches=['floating-point']
                        if val.lower() in ('ulaw','u-law'):matches=['mu-law']
                        if not matches:ctx.fail('sox',"--encoding: `%s' is not a supported encoding"%val)
                        current[key]=matches[0]
                    else:
                        if val not in ('little','big','swap'):ctx.fail('sox','--endian: must be little, big, or swap.')
                        current[key]=val
                elif key in ('little','big','swap'):current['endian']=key
                elif key in ('bits','rate','channels','volume','compression'):
                    try:
                        v=parse_number(val,key=='rate')
                        if not math.isfinite(v):raise ValueError()
                        if key in ('bits','channels'):
                            if v!=int(v) or v<=0:raise ValueError()
