                        if key=='rate' and v<=0:raise ValueError()
                    except (ValueError,OverflowError):
                        label={'bits':'Bits','rate':'Rate','channels':'Channels','volume':'Volume','compression':'Compression'}[key]
                        ctx.fail('sox',"%s value `%s' is not a %s"%(label,val,'positive integer' if key in ('bits','channels') else 'positive number' if key=='rate' else 'number'))
