                if silent_count>=abs(below):
                    cut=pos+1 if leave else pos-run+1
                    out.extend(a.data[lastcopy*a.channels:cut*a.channels])
                    if below>0:return a.modified(out)
                    pos+=1
                    while pos<n and levels[pos]<=max(bt,at):pos+=1
                    lastcopy=pos;run=0;silent_count=0;continue
                run=-1000000000
        else:run=0
